import SwiftUI
import UniformTypeIdentifiers

struct LibraryView: View {
    @EnvironmentObject private var container: AppContainer
    @EnvironmentObject private var audioPlayer: AudioPlayerService
    @ObservedObject var coordinator: AppCoordinator
    @State private var showingImporter = false
    @State private var importMessage: String?
    let filters = ["All", "Songs", "Albums", "Artists", "Playlists"]
    var body: some View { ScrollView { VStack(alignment: .leading, spacing: AppSpacing.xl) { HStack(alignment: .center) { Text("Library").font(.largeTitle.bold()).foregroundStyle(AppColors.textPrimary); Spacer(); Button { showingImporter = true } label: { Label("Import", systemImage: "square.and.arrow.down").lineLimit(1) }.buttonStyle(.borderedProminent).tint(AppColors.accentPrimary).foregroundStyle(.black).frame(minHeight: 44) }; if let importMessage { Text(importMessage).font(.callout).foregroundStyle(AppColors.textSecondary).fixedSize(horizontal: false, vertical: true) }; ScrollView(.horizontal, showsIndicators: false) { HStack(spacing: AppSpacing.sm) { ForEach(filters, id: \.self) { filter in FilterChip(title: filter, selected: coordinator.libraryFilter == filter) { coordinator.libraryFilter = filter } } } }; if let imported = container.storage?.library, !imported.isEmpty { HStack { Text("Imported Music").font(.title3.weight(.semibold)).foregroundStyle(AppColors.textPrimary); Spacer(); Text(imported.count == 1 ? "1 track" : "\(imported.count) tracks").font(.callout).foregroundStyle(AppColors.textSecondary) }; ForEach(imported) { StoredTrackRow(track: $0) } }; content }.padding(.horizontal, AppSpacing.lg).padding(.top, AppSpacing.md).padding(.bottom, 100) }.navigationBarHidden(true).screenBackground().fileImporter(isPresented: $showingImporter, allowedContentTypes: [.audio, .supportedAudio], allowsMultipleSelection: false) { result in Task { @MainActor in do { guard let url = try result.get().first, let storage = container.storage else { return }; let imported = try await storage.importAudio(from: url); storage.reload(); audioPlayer.refreshContext(); importMessage = imported.duplicate ? "Already imported: \(imported.track.title)" : "Imported \(imported.track.title)" } catch { importMessage = error.localizedDescription } } } }
    @ViewBuilder private var content: some View { switch coordinator.libraryFilter { case "Albums": LazyVGrid(columns: [GridItem(.adaptive(minimum: 140), spacing: AppSpacing.lg)], spacing: AppSpacing.xl) { ForEach(container.music.albums) { album in NavigationLink { AlbumDetailView(album: album) } label: { AlbumCard(album: album) } } }; case "Artists": ForEach(container.music.artists) { artist in NavigationLink { ArtistDetailView(artist: artist) } label: { HStack { ArtworkView(name: artist.artwork, size: 56); Text(artist.name).foregroundStyle(AppColors.textPrimary); Spacer(); Text("\(artist.trackIDs.count) songs").font(.caption).foregroundStyle(AppColors.textSecondary) } } }; case "Playlists": ForEach(container.music.playlists) { playlist in NavigationLink { PlaylistDetailView(playlistID: playlist.id) } label: { HStack { ArtworkView(name: playlist.id, size: 64); VStack(alignment: .leading) { Text(playlist.name).foregroundStyle(AppColors.textPrimary); Text("\(playlist.trackIDs.count) tracks").font(.caption).foregroundStyle(AppColors.textSecondary) }; Spacer(); Image(systemName: "chevron.right").foregroundStyle(AppColors.textTertiary) } } }; default: if container.storage?.library.isEmpty ?? true { EmptyState(icon: "music.note", title: "Your library is empty", message: "Import an MP3, M4A, or other local audio file.", actionTitle: "Import Audio") { showingImporter = true } } else { EmptyView() } } }
}

struct StoredTrackRow: View {
    @EnvironmentObject private var container: AppContainer
    let track: StoredTrack
    @State private var showingExporter = false
    @State private var exportDocument: AudioExportDocument?
    @State private var exportError: String?
    private var subtitle: String {
        let artist = container.storage?.artistName(for: track.artistID)
        let fallback = track.originalFilename ?? track.fileRelativePath
        return artist?.isEmpty == false ? artist! : fallback
    }
    private var duration: String? { guard let milliseconds = track.durationMs else { return nil }; return String(format: "%d:%02d", milliseconds / 60000, (milliseconds / 1000) % 60) }
    var body: some View { HStack(spacing: AppSpacing.md) { StoredArtworkView(track: track, size: 54); VStack(alignment: .leading, spacing: AppSpacing.xs) { Text(track.title).font(.subheadline.weight(.semibold)).foregroundStyle(AppColors.textPrimary).lineLimit(1).truncationMode(.tail); HStack(spacing: AppSpacing.xs) { Text(subtitle).font(.caption).foregroundStyle(AppColors.textSecondary).lineLimit(1).truncationMode(.tail); if let duration { Text("• \(duration)").font(.caption2).foregroundStyle(AppColors.textTertiary).lineLimit(1) } }; Text(track.availability == .available ? "Available" : track.availability.rawValue.capitalized).font(.caption2).foregroundStyle(track.availability == .available ? AppColors.success : AppColors.warning).lineLimit(1); if let exportError { Text(exportError).font(.caption2).foregroundStyle(AppColors.error).lineLimit(2) } }.layoutPriority(1); Spacer(minLength: AppSpacing.xs); Menu { Button { export() } label: { Label("Export", systemImage: "square.and.arrow.up") }; Button {} label: { Label("Edit metadata", systemImage: "pencil") } } label: { Image(systemName: "ellipsis").foregroundStyle(AppColors.textSecondary).frame(width: 44, height: 44) }.buttonStyle(.plain).accessibilityLabel("Actions for \(track.title)") }.padding(.vertical, AppSpacing.xs).contentShape(Rectangle()).onTapGesture { Task { try? await container.audioPlayer.play(trackID: track.id) } }.accessibilityIdentifier("stored-track-row-\(track.id)").fileExporter(isPresented: $showingExporter, document: exportDocument, contentType: .audio, defaultFilename: track.originalFilename ?? track.title) { result in if case .failure(let error) = result { exportError = error.localizedDescription } } }
    private func export() { do { guard let storage = container.storage else { throw StorageError.databaseUnavailable("Storage is unavailable") }; let url = try storage.paths.musicURL(relativePath: track.fileRelativePath); exportDocument = AudioExportDocument(data: try Data(contentsOf: url)); showingExporter = true } catch { exportError = error.localizedDescription } }
}

struct PlaylistDetailView: View {
    @EnvironmentObject private var container: AppContainer
    let playlistID: String
    @State private var showingEditor = false
    var body: some View { let playlist = container.music.playlists.first { $0.id == playlistID }; ScrollView { VStack(alignment: .leading, spacing: AppSpacing.lg) { if let playlist { ArtworkView(name: playlist.id, size: 220).frame(maxWidth: .infinity); Text(playlist.name).font(.title.bold()).foregroundStyle(AppColors.textPrimary); Text(playlist.description).foregroundStyle(AppColors.textSecondary); ForEach(playlist.trackIDs.compactMap { container.music.track($0) }) { TrackRow(track: $0) } } }.padding(AppSpacing.xl).padding(.bottom, 100) }.navigationTitle("Playlist").navigationBarTitleDisplayMode(.inline).toolbar { ToolbarItem(placement: .primaryAction) { Button { showingEditor = true } label: { Image(systemName: "pencil") }.accessibilityLabel("Edit Playlist") } }.screenBackground().sheet(isPresented: $showingEditor) { PlaylistEditorView(playlistID: playlistID) } }
}

